/**
 * Content model for the site. Everything editable from /admin lives in a single
 * `SiteContent` object, serialised as src/content/content.json.
 */

/** Nature of a piece of media, shown to visitors so renders and illustrations are never mistaken for documentation. */
export type MediaKind = 'photo' | 'rendu' | 'schema' | 'illustration' | 'video';

export interface MediaRef {
  /**
   * `/media/photos/<key>` (responsive WebP set generated by tools/prepare_assets.py),
   * a direct file URL (`/media/x.jpg`, `https://…`), or `idb:<id>` for an image
   * imported in the admin and stored in this browser only.
   */
  src: string;
  alt: string;
  kind: MediaKind;
  caption?: string;
  credit?: string;
}

export type Verification = 'documente' | 'partiel' | 'a-documenter';

export interface Parameter {
  label: string;
  value: string;
  /** id of an entry in `SiteContent.sources` */
  source?: string;
}

export interface StepComponent {
  id: string;
  order: number;
  visible: boolean;
  /** Shown as a step in chapter 04 « Les ouvrages » */
  inNarrative: boolean;
  name: string;
  technicalName?: string;
  /** id of an entry in `SiteContent.stages` */
  stage?: string;
  verification: Verification;
  shortDescription: string;
  role?: string;
  details?: string;
  /** Part ids from public/models/manifest.json that make up this structure in the 3D model */
  modelParts: string[];
  photos: MediaRef[];
  render?: MediaRef;
  diagram?: MediaRef;
  video?: MediaRef;
  parameters: Parameter[];
  sources: string[];
  /** Editorial note shown under the sources (e.g. what remains to be verified) */
  note?: string;
}

export interface Stage {
  id: string;
  label: string;
}

export interface Source {
  id: string;
  label: string;
  detail?: string;
}

export type SectionId = 'hero' | 'parcours' | 'explorer' | 'ouvrages' | 'apres' | 'apropos';

export interface Chapter {
  id: string;
  number: string;
  eyebrow: string;
  title: string;
  text: string;
  secondary?: string;
  secondarySource?: string;
  media?: MediaRef;
  visible: boolean;
}

export interface Credit {
  role: string;
  name: string;
}

export interface SiteContent {
  version: 1;
  hero: {
    eyebrow: string;
    title: string;
    subtitle: string;
    description: string;
    primaryCta: string;
    secondaryCta: string;
    media: MediaRef;
  };
  chapters: Chapter[];
  stages: Stage[];
  components: StepComponent[];
  facts: Parameter[];
  sources: Source[];
  about: {
    title: string;
    text: string;
    signature: string;
    disclaimer: string;
    credits: Credit[];
  };
  sections: Record<SectionId, boolean>;
}
